        assertEquals(NOT_FOUND, StringUtils.lastIndexOf(null, null, 0));
        assertEquals(NOT_FOUND, StringUtils.lastIndexOf(null, null, -1));
        assertEquals(NOT_FOUND, StringUtils.lastIndexOf(null, "", 0));
