    @Test
    public void testLastIndexOf_charInt() {
        assertEquals(NOT_FOUND, StringUtils.lastIndexOf(null, ' ', 0));
        assertEquals(NOT_FOUND, StringUtils.lastIndexOf(null, ' ', -1));
        assertEquals(NOT_FOUND, StringUtils.lastIndexOf("", ' ', 0));
        assertEquals(NOT_FOUND, StringUtils.lastIndexOf("", ' ', -1));
        assertEquals(7, StringUtils.lastIndexOf("aabaabaa", 'a', 8));
        assertEquals(5, StringUtils.lastIndexOf("aabaabaa", 'b', 8));
        assertEquals(2, StringUtils.lastIndexOf("aabaabaa", 'b', 3));
        assertEquals(5, StringUtils.lastIndexOf("aabaabaa", 'b', 9));
        assertEquals(NOT_FOUND, StringUtils.lastIndexOf("aabaabaa", 'b', -1));
        assertEquals(0, StringUtils.lastIndexOf("aabaabaa", 'a', 0));

        assertEquals(2, StringUtils.lastIndexOf(new StringBuilder("aabaabaa"), 'b', 2));
        CharBuffer charBuffer = CharBuffer.allocate(93);
        CharSequence charSequence = CharSequenceUtils.subSequence(charBuffer, 93);
        assertEquals(NOT_FOUND, StringUtils.indexOf(charSequence, 553, (-1392)));
        assertEquals(NOT_FOUND, StringUtils.indexOf(charBuffer, (-1), (-1392)));
        //LANG-1300 addition test
        final int CODE_POINT = 0x2070E;
        StringBuilder builder = new StringBuilder();
        builder.appendCodePoint(CODE_POINT);
        assertEquals(0, StringUtils.lastIndexOf(builder, CODE_POINT, 0));
        builder.appendCodePoint(CODE_POINT);
        assertEquals(0, StringUtils.lastIndexOf(builder, CODE_POINT, 0));
        assertEquals(0, StringUtils.lastIndexOf(builder, CODE_POINT, 1));
        assertEquals(2, StringUtils.lastIndexOf(builder, CODE_POINT, 2));

        builder.append("aaaaa");
        assertEquals(2, StringUtils.lastIndexOf(builder, CODE_POINT, 4));
        // inner branch on the supplementary character block
        final char[] tmp = { (char) 55361 };
        builder = new StringBuilder();
        builder.append(tmp);
        assertEquals(NOT_FOUND, StringUtils.lastIndexOf(builder, CODE_POINT, 0));
        builder.appendCodePoint(CODE_POINT);
        assertEquals(NOT_FOUND, StringUtils.lastIndexOf(builder, CODE_POINT, 0));
        assertEquals(1, StringUtils.lastIndexOf(builder, CODE_POINT, 1 ));
        assertEquals(NOT_FOUND, StringUtils.lastIndexOf(builder.toString(), CODE_POINT, 0));
        assertEquals(1, StringUtils.lastIndexOf(builder.toString(), CODE_POINT, 1));
    }

    @Test
    public void testLastIndexOf_String() {
        assertEquals(NOT_FOUND, StringUtils.lastIndexOf(null, null));
        assertEquals(NOT_FOUND, StringUtils.lastIndexOf("", null));
        assertEquals(NOT_FOUND, StringUtils.lastIndexOf("", "a"));
        assertEquals(0, StringUtils.lastIndexOf("", ""));
        assertEquals(8, StringUtils.lastIndexOf("aabaabaa", ""));
        assertEquals(7, StringUtils.lastIndexOf("aabaabaa", "a"));
        assertEquals(5, StringUtils.lastIndexOf("aabaabaa", "b"));
        assertEquals(4, StringUtils.lastIndexOf("aabaabaa", "ab"));

        assertEquals(4, StringUtils.lastIndexOf(new StringBuilder("aabaabaa"), "ab"));
    }

    @Test
    public void testLastIndexOf_StringInt() {
        assertEquals(NOT_FOUND, StringUtils.lastIndexOf(null, null, 0));
        assertEquals(NOT_FOUND, StringUtils.lastIndexOf(null, null, -1));
        assertEquals(NOT_FOUND, StringUtils.lastIndexOf(null, "", 0));
        assertEquals(NOT_FOUND, StringUtils.lastIndexOf(null, "", -1));
        assertEquals(NOT_FOUND, StringUtils.lastIndexOf("", null, 0));
        assertEquals(NOT_FOUND, StringUtils.lastIndexOf("", null, -1));
        assertEquals(0, StringUtils.lastIndexOf("", "", 0));
        assertEquals(NOT_FOUND, StringUtils.lastIndexOf("", "", -1));
        assertEquals(0, StringUtils.lastIndexOf("", "", 9));
        assertEquals(0, StringUtils.lastIndexOf("abc", "", 0));
        assertEquals(NOT_FOUND, StringUtils.lastIndexOf("abc", "", -1));
        assertEquals(3, StringUtils.lastIndexOf("abc", "", 9));
        assertEquals(7, StringUtils.lastIndexOf("aabaabaa", "a", 8));
        assertEquals(5, StringUtils.lastIndexOf("aabaabaa", "b", 8));
        assertEquals(4, StringUtils.lastIndexOf("aabaabaa", "ab", 8));
        assertEquals(2, StringUtils.lastIndexOf("aabaabaa", "b", 3));
        assertEquals(5, StringUtils.lastIndexOf("aabaabaa", "b", 9));
        assertEquals(NOT_FOUND, StringUtils.lastIndexOf("aabaabaa", "b", -1));
        assertEquals(NOT_FOUND, StringUtils.lastIndexOf("aabaabaa", "b", 0));
        assertEquals(0, StringUtils.lastIndexOf("aabaabaa", "a", 0));
        assertEquals(NOT_FOUND, StringUtils.lastIndexOf("aabaabaa", "a", -1));

        // Test that fromIndex works correctly, i.e. cannot match after fromIndex
        assertEquals(7, StringUtils.lastIndexOf("12345678", "8", 9));
        assertEquals(7, StringUtils.lastIndexOf("12345678", "8", 8));
        assertEquals(7, StringUtils.lastIndexOf("12345678", "8", 7)); // 7 is last index
        assertEquals(NOT_FOUND, StringUtils.lastIndexOf("12345678", "8", 6));

        assertEquals(NOT_FOUND, StringUtils.lastIndexOf("aabaabaa", "b", 1));
        assertEquals(2, StringUtils.lastIndexOf("aabaabaa", "b", 2));
        assertEquals(2, StringUtils.lastIndexOf("aabaabaa", "ba", 2));
        assertEquals(2, StringUtils.lastIndexOf("aabaabaa", "ba", 3));

        assertEquals(2, StringUtils.lastIndexOf(new StringBuilder("aabaabaa"), "b", 3));
    }

    @Test
    public void testLastIndexOfAny_StringStringArray() {
        assertEquals(NOT_FOUND, StringUtils.lastIndexOfAny(null, (CharSequence) null));   // test both types of ...
        assertEquals(NOT_FOUND, StringUtils.lastIndexOfAny(null, (CharSequence[]) null)); // ... varargs invocation
        assertEquals(NOT_FOUND, StringUtils.lastIndexOfAny(null)); // Missing varag
        assertEquals(NOT_FOUND, StringUtils.lastIndexOfAny(null, FOOBAR_SUB_ARRAY));
        assertEquals(NOT_FOUND, StringUtils.lastIndexOfAny(FOOBAR, (CharSequence) null));   // test both types of ...
        assertEquals(NOT_FOUND, StringUtils.lastIndexOfAny(FOOBAR, (CharSequence[]) null)); // ... varargs invocation
        assertEquals(NOT_FOUND, StringUtils.lastIndexOfAny(FOOBAR)); // Missing vararg
        assertEquals(3, StringUtils.lastIndexOfAny(FOOBAR, FOOBAR_SUB_ARRAY));
        assertEquals(NOT_FOUND, StringUtils.lastIndexOfAny(FOOBAR, new String[0]));
        assertEquals(NOT_FOUND, StringUtils.lastIndexOfAny(null, new String[0]));
        assertEquals(NOT_FOUND, StringUtils.lastIndexOfAny("", new String[0]));
        assertEquals(NOT_FOUND, StringUtils.lastIndexOfAny(FOOBAR, new String[] {"llll"}));
        assertEquals(6, StringUtils.lastIndexOfAny(FOOBAR, new String[] {""}));
        assertEquals(0, StringUtils.lastIndexOfAny("", new String[] {""}));
        assertEquals(NOT_FOUND, StringUtils.lastIndexOfAny("", new String[] {"a"}));
        assertEquals(NOT_FOUND, StringUtils.lastIndexOfAny("", new String[] {null}));
        assertEquals(NOT_FOUND, StringUtils.lastIndexOfAny(FOOBAR, new String[] {null}));
        assertEquals(NOT_FOUND, StringUtils.lastIndexOfAny(null, new String[] {null}));
    }

    @Test
    public void testLastIndexOfIgnoreCase_String() {
        assertEquals(NOT_FOUND, StringUtils.lastIndexOfIgnoreCase(null, null));
        assertEquals(NOT_FOUND, StringUtils.lastIndexOfIgnoreCase("", null));
        assertEquals(NOT_FOUND, StringUtils.lastIndexOfIgnoreCase(null, ""));
        assertEquals(NOT_FOUND, StringUtils.lastIndexOfIgnoreCase("", "a"));
        assertEquals(0, StringUtils.lastIndexOfIgnoreCase("", ""));
        assertEquals(8, StringUtils.lastIndexOfIgnoreCase("aabaabaa", ""));
        assertEquals(7, StringUtils.lastIndexOfIgnoreCase("aabaabaa", "a"));
        assertEquals(7, StringUtils.lastIndexOfIgnoreCase("aabaabaa", "A"));
        assertEquals(5, StringUtils.lastIndexOfIgnoreCase("aabaabaa", "b"));
        assertEquals(5, StringUtils.lastIndexOfIgnoreCase("aabaabaa", "B"));
        assertEquals(4, StringUtils.lastIndexOfIgnoreCase("aabaabaa", "ab"));
        assertEquals(4, StringUtils.lastIndexOfIgnoreCase("aabaabaa", "AB"));
        assertEquals(NOT_FOUND, StringUtils.lastIndexOfIgnoreCase("ab", "AAB"));
        assertEquals(0, StringUtils.lastIndexOfIgnoreCase("aab", "AAB"));
    }

    @Test
    public void testLastIndexOfIgnoreCase_StringInt() {
        assertEquals(NOT_FOUND, StringUtils.lastIndexOfIgnoreCase(null, null, 0));
        assertEquals(NOT_FOUND, StringUtils.lastIndexOfIgnoreCase(null, null, -1));
        assertEquals(NOT_FOUND, StringUtils.lastIndexOfIgnoreCase(null, "", 0));
        assertEquals(NOT_FOUND, StringUtils.lastIndexOfIgnoreCase(null, "", -1));
        assertEquals(NOT_FOUND, StringUtils.lastIndexOfIgnoreCase("", null, 0));
        assertEquals(NOT_FOUND, StringUtils.lastIndexOfIgnoreCase("", null, -1));
        assertEquals(0, StringUtils.lastIndexOfIgnoreCase("", "", 0));
        assertEquals(NOT_FOUND, StringUtils.lastIndexOfIgnoreCase("", "", -1));
        assertEquals(0, StringUtils.lastIndexOfIgnoreCase("", "", 9));
        assertEquals(0, StringUtils.lastIndexOfIgnoreCase("abc", "", 0));
        assertEquals(NOT_FOUND, StringUtils.lastIndexOfIgnoreCase("abc", "", -1));
        assertEquals(3, StringUtils.lastIndexOfIgnoreCase("abc", "", 9));
        assertEquals(7, StringUtils.lastIndexOfIgnoreCase("aabaabaa", "A", 8));
        assertEquals(5, StringUtils.lastIndexOfIgnoreCase("aabaabaa", "B", 8));
        assertEquals(4, StringUtils.lastIndexOfIgnoreCase("aabaabaa", "AB", 8));
        assertEquals(2, StringUtils.lastIndexOfIgnoreCase("aabaabaa", "B", 3));
        assertEquals(5, StringUtils.lastIndexOfIgnoreCase("aabaabaa", "B", 9));
        assertEquals(NOT_FOUND, StringUtils.lastIndexOfIgnoreCase("aabaabaa", "B", -1));
        assertEquals(NOT_FOUND, StringUtils.lastIndexOfIgnoreCase("aabaabaa", "B", 0));
        assertEquals(0, StringUtils.lastIndexOfIgnoreCase("aabaabaa", "A", 0));
        assertEquals(1, StringUtils.lastIndexOfIgnoreCase("aab", "AB", 1));
    }

    @Test
    public void testLastOrdinalIndexOf() {
        assertEquals(NOT_FOUND, StringUtils.lastOrdinalIndexOf(null, "*", 42) );
        assertEquals(NOT_FOUND, StringUtils.lastOrdinalIndexOf("*", null, 42) );
        assertEquals(0, StringUtils.lastOrdinalIndexOf("", "", 42) );
        assertEquals(7, StringUtils.lastOrdinalIndexOf("aabaabaa", "a", 1) );
        assertEquals(6, StringUtils.lastOrdinalIndexOf("aabaabaa", "a", 2) );
        assertEquals(5, StringUtils.lastOrdinalIndexOf("aabaabaa", "b", 1) );
        assertEquals(2, StringUtils.lastOrdinalIndexOf("aabaabaa", "b", 2) );
        assertEquals(4, StringUtils.lastOrdinalIndexOf("aabaabaa", "ab", 1) );
        assertEquals(1, StringUtils.lastOrdinalIndexOf("aabaabaa", "ab", 2) );
        assertEquals(8, StringUtils.lastOrdinalIndexOf("aabaabaa", "", 1) );
        assertEquals(8, StringUtils.lastOrdinalIndexOf("aabaabaa", "", 2) );
    }

    @Test
    public void testOrdinalIndexOf() {
        assertEquals(NOT_FOUND, StringUtils.ordinalIndexOf(null, null, Integer.MIN_VALUE));
        assertEquals(NOT_FOUND, StringUtils.ordinalIndexOf("", null, Integer.MIN_VALUE));
        assertEquals(NOT_FOUND, StringUtils.ordinalIndexOf("", "", Integer.MIN_VALUE));
        assertEquals(NOT_FOUND, StringUtils.ordinalIndexOf("aabaabaa", "a", Integer.MIN_VALUE));
        assertEquals(NOT_FOUND, StringUtils.ordinalIndexOf("aabaabaa", "b", Integer.MIN_VALUE));
        assertEquals(NOT_FOUND, StringUtils.ordinalIndexOf("aabaabaa", "ab", Integer.MIN_VALUE));
        assertEquals(NOT_FOUND, StringUtils.ordinalIndexOf("aabaabaa", "", Integer.MIN_VALUE));

        assertEquals(NOT_FOUND, StringUtils.ordinalIndexOf(null, null, -1));
        assertEquals(NOT_FOUND, StringUtils.ordinalIndexOf("", null, -1));
        assertEquals(NOT_FOUND, StringUtils.ordinalIndexOf("", "", -1));
        assertEquals(NOT_FOUND, StringUtils.ordinalIndexOf("aabaabaa", "a", -1));
        assertEquals(NOT_FOUND, StringUtils.ordinalIndexOf("aabaabaa", "b", -1));
        assertEquals(NOT_FOUND, StringUtils.ordinalIndexOf("aabaabaa", "ab", -1));
        assertEquals(NOT_FOUND, StringUtils.ordinalIndexOf("aabaabaa", "", -1));

        assertEquals(NOT_FOUND, StringUtils.ordinalIndexOf(null, null, 0));
        assertEquals(NOT_FOUND, StringUtils.ordinalIndexOf("", null, 0));
        assertEquals(NOT_FOUND, StringUtils.ordinalIndexOf("", "", 0));
        assertEquals(NOT_FOUND, StringUtils.ordinalIndexOf("aabaabaa", "a", 0));
        assertEquals(NOT_FOUND, StringUtils.ordinalIndexOf("aabaabaa", "b", 0));
        assertEquals(NOT_FOUND, StringUtils.ordinalIndexOf("aabaabaa", "ab", 0));
        assertEquals(NOT_FOUND, StringUtils.ordinalIndexOf("aabaabaa", "", 0));

        assertEquals(NOT_FOUND, StringUtils.ordinalIndexOf(null, null, 1));
        assertEquals(NOT_FOUND, StringUtils.ordinalIndexOf("", null, 1));
        assertEquals(0, StringUtils.ordinalIndexOf("", "", 1));
        assertEquals(0, StringUtils.ordinalIndexOf("aabaabaa", "a", 1));
        assertEquals(2, StringUtils.ordinalIndexOf("aabaabaa", "b", 1));
        assertEquals(1, StringUtils.ordinalIndexOf("aabaabaa", "ab", 1));
        assertEquals(0, StringUtils.ordinalIndexOf("aabaabaa", "", 1));

        assertEquals(NOT_FOUND, StringUtils.ordinalIndexOf(null, null, 2));
        assertEquals(NOT_FOUND, StringUtils.ordinalIndexOf("", null, 2));
        assertEquals(0, StringUtils.ordinalIndexOf("", "", 2));
        assertEquals(1, StringUtils.ordinalIndexOf("aabaabaa", "a", 2));
        assertEquals(5, StringUtils.ordinalIndexOf("aabaabaa", "b", 2));
        assertEquals(4, StringUtils.ordinalIndexOf("aabaabaa", "ab", 2));
        assertEquals(0, StringUtils.ordinalIndexOf("aabaabaa", "", 2));

        assertEquals(NOT_FOUND, StringUtils.ordinalIndexOf(null, null, Integer.MAX_VALUE));
        assertEquals(NOT_FOUND, StringUtils.ordinalIndexOf("", null, Integer.MAX_VALUE));
        assertEquals(0, StringUtils.ordinalIndexOf("", "", Integer.MAX_VALUE));
        assertEquals(NOT_FOUND, StringUtils.ordinalIndexOf("aabaabaa", "a", Integer.MAX_VALUE));
        assertEquals(NOT_FOUND, StringUtils.ordinalIndexOf("aabaabaa", "b", Integer.MAX_VALUE));
        assertEquals(NOT_FOUND, StringUtils.ordinalIndexOf("aabaabaa", "ab", Integer.MAX_VALUE));
        assertEquals(0, StringUtils.ordinalIndexOf("aabaabaa", "", Integer.MAX_VALUE));

        assertEquals(NOT_FOUND, StringUtils.ordinalIndexOf("aaaaaaaaa", "a", 0));
        assertEquals(0, StringUtils.ordinalIndexOf("aaaaaaaaa", "a", 1));
        assertEquals(1, StringUtils.ordinalIndexOf("aaaaaaaaa", "a", 2));
        assertEquals(2, StringUtils.ordinalIndexOf("aaaaaaaaa", "a", 3));
        assertEquals(3, StringUtils.ordinalIndexOf("aaaaaaaaa", "a", 4));
        assertEquals(4, StringUtils.ordinalIndexOf("aaaaaaaaa", "a", 5));
        assertEquals(5, StringUtils.ordinalIndexOf("aaaaaaaaa", "a", 6));
        assertEquals(6, StringUtils.ordinalIndexOf("aaaaaaaaa", "a", 7));
        assertEquals(7, StringUtils.ordinalIndexOf("aaaaaaaaa", "a", 8));
        assertEquals(8, StringUtils.ordinalIndexOf("aaaaaaaaa", "a", 9));
        assertEquals(NOT_FOUND, StringUtils.ordinalIndexOf("aaaaaaaaa", "a", 10));

        // match at each possible position
        assertEquals(0, StringUtils.ordinalIndexOf("aaaaaa", "aa", 1));
        assertEquals(1, StringUtils.ordinalIndexOf("aaaaaa", "aa", 2));
        assertEquals(2, StringUtils.ordinalIndexOf("aaaaaa", "aa", 3));
        assertEquals(3, StringUtils.ordinalIndexOf("aaaaaa", "aa", 4));
        assertEquals(4, StringUtils.ordinalIndexOf("aaaaaa", "aa", 5));
        assertEquals(NOT_FOUND, StringUtils.ordinalIndexOf("aaaaaa", "aa", 6));

        assertEquals(0, StringUtils.ordinalIndexOf("ababab", "aba", 1));
        assertEquals(2, StringUtils.ordinalIndexOf("ababab", "aba", 2));
        assertEquals(NOT_FOUND, StringUtils.ordinalIndexOf("ababab", "aba", 3));

        assertEquals(0, StringUtils.ordinalIndexOf("abababab", "abab", 1));
        assertEquals(2, StringUtils.ordinalIndexOf("abababab", "abab", 2));
        assertEquals(4, StringUtils.ordinalIndexOf("abababab", "abab", 3));
        assertEquals(NOT_FOUND, StringUtils.ordinalIndexOf("abababab", "abab", 4));
    }

    @Test
    public void testLANG1193() {
        assertEquals(0, StringUtils.ordinalIndexOf("abc", "ab", 1));
    }

    @Test
    // Non-overlapping test
    public void testLANG1241_1() {
        //                                          0  3  6
        assertEquals(0, StringUtils.ordinalIndexOf("abaabaab", "ab", 1));
        assertEquals(3, StringUtils.ordinalIndexOf("abaabaab", "ab", 2));
        assertEquals(6, StringUtils.ordinalIndexOf("abaabaab", "ab", 3));
    }

    @Test
    // Overlapping matching test
    public void testLANG1241_2() {
        //                                          0 2 4
        assertEquals(0, StringUtils.ordinalIndexOf("abababa", "aba", 1));
        assertEquals(2, StringUtils.ordinalIndexOf("abababa", "aba", 2));
        assertEquals(4, StringUtils.ordinalIndexOf("abababa", "aba", 3));
        assertEquals(0, StringUtils.ordinalIndexOf("abababab", "abab", 1));
        assertEquals(2, StringUtils.ordinalIndexOf("abababab", "abab", 2));
        assertEquals(4, StringUtils.ordinalIndexOf("abababab", "abab", 3));
    }
}

